uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
uniform shader amzt_edgeBuf;
float4 amzSample_edgeBuf(float2 uv) { return float4(amzt_edgeBuf.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/2.0))); }
uniform shader amzt_glowH;
float4 amzSample_glowH(float2 uv) { return float4(amzt_glowH.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/2.0))); }
uniform shader amzt_glowV;
float4 amzSample_glowV(float2 uv) { return float4(amzt_glowV.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/2.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_edgeBuf(uv);if(tex==2) return amzSample_glowH(uv);if(tex==3) return amzSample_glowV(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_edgeStrength;
uniform float amzp_edgeThickness;
uniform float amzp_edgeThreshold;
uniform float amzp_edgeSoftness;
uniform float amzp_edgeType;
uniform float amzp_glowAmount;
uniform float amzp_glowRadius;
uniform float amzp_glowFalloff;
uniform float amzp_innerGlow;
uniform float amzp_innerRadius;
uniform float amzp_innerSoftness;
uniform float amzp_outerGlow;
