uniform float amzp_quality;
uniform float amzp_edgeOnly;
uniform float amzp_glowOnly;
uniform float amzp_ditherAmt;
uniform float amzp_globalMix;
    float lum(float3 c) {
        return dot(c, float3(0.2126, 0.7152, 0.0722));
    }
    float3 rgb2hsl(float3 c) {
        float mx = max(c.r, max(c.g, c.b));
        float mn = min(c.r, min(c.g, c.b));
        float l = (mx + mn) * 0.5;
        float d = mx - mn;
        float s = 0.0;
        float h = 0.0;
        if (d > 0.00001) {
            s = (l > 0.5) ? d / max(2.0 - mx - mn, 0.00001) : d / max(mx + mn, 0.00001);
            if (mx == c.r) { h = (c.g - c.b) / d + (c.g < c.b ? 6.0 : 0.0); }
            else if (mx == c.g) { h = (c.b - c.r) / d + 2.0; }
            else { h = (c.r - c.g) / d + 4.0; }
            h /= 6.0;
        }
        return float3(h, s, l);
    }
    float h2r(float p, float q, float t) {
        if (t < 0.0) t += 1.0;
        if (t > 1.0) t -= 1.0;
        if (t < 1.0/6.0) return p + (q - p) * 6.0 * t;
        if (t < 0.5) return q;
        if (t < 2.0/3.0) return p + (q - p) * (2.0/3.0 - t) * 6.0;
        return p;
    }
    float3 hsl2rgb(float3 c) {
        if (c.y < 0.00001) return float3(c.z);
        float q = (c.z < 0.5) ? c.z * (1.0 + c.y) : c.z + c.y - c.z * c.y;
        float p = 2.0 * c.z - q;
        return float3(h2r(p,q,c.x+1.0/3.0), h2r(p,q,c.x), h2r(p,q,c.x-1.0/3.0));
    }
    float getTaps(float q) {
        if (q < 1.5) return 10.0;
        if (q < 2.5) return 18.0;
        return 28.0;
    }
    float4 separableBlur(int tex, float2 uv, float2 dir, float radius, float taps) {
        if (radius <= 0.5) return amzTexture(tex, uv);
        float sigma = radius / 2.14596602;
        sigma = max(sigma, 0.00001);
        float baseCoeff = 1.0 / (sqrt(2.0 * 3.14159265359) * sigma);
        float decayRate = exp(-0.5 / (sigma * sigma));
        float decaySq = decayRate * decayRate;
        float4 acc = amzTexture(tex, uv) * baseCoeff;
        float wSum = baseCoeff;
        float coeff = baseCoeff;
        float decay = decayRate;
        for (float i = 1.0; i <= 256.0; i += 2.0) {
            if (i > taps) break;
            float p0 = i;
            float p1 = i + 1.0;
            coeff *= decay;
            wSum += 2.0 * coeff;
            float w0 = coeff;
            coeff *= decay;
            decay *= decaySq;
            wSum += 2.0 * coeff;
            float w1 = coeff;
            float wPair = w0 + w1;
            float oPair = (p0*w0 + p1*w1) / max(wPair, 0.00001);
            float2 uvA = clamp(uv - oPair * dir, 0.0, 1.0);
            float2 uvB = clamp(uv + oPair * dir, 0.0, 1.0);
            acc += amzTexture(tex, uvA) * wPair;
            acc += amzTexture(tex, uvB) * wPair;
        }
        return acc / max(wSum, 0.00001);
    }
    float detectEdgeLuminance(float2 uv, float2 px, float thick) {
        float2 o = px * thick;
        float c = lum(amzTexture(0, uv).rgb);
        float t = lum(amzTexture(0, clamp(uv + float2(0.0, -o.y), 0.0, 1.0)).rgb);
        float b = lum(amzTexture(0, clamp(uv + float2(0.0, o.y), 0.0, 1.0)).rgb);
        float l = lum(amzTexture(0, clamp(uv + float2(-o.x, 0.0), 0.0, 1.0)).rgb);
        float r = lum(amzTexture(0, clamp(uv + float2(o.x, 0.0), 0.0, 1.0)).rgb);
        float edge = abs(t - b) + abs(l - r);
        return edge;
    }
    float detectEdgeSobel(float2 uv, float2 px, float thick) {
        float2 o = px * thick;
        float tl = lum(amzTexture(0, clamp(uv + float2(-o.x, -o.y), 0.0, 1.0)).rgb);
        float tc = lum(amzTexture(0, clamp(uv + float2(0.0, -o.y), 0.0, 1.0)).rgb);
        float tr = lum(amzTexture(0, clamp(uv + float2(o.x, -o.y), 0.0, 1.0)).rgb);
        float ml = lum(amzTexture(0, clamp(uv + float2(-o.x, 0.0), 0.0, 1.0)).rgb);
        float mr = lum(amzTexture(0, clamp(uv + float2(o.x, 0.0), 0.0, 1.0)).rgb);
        float bl = lum(amzTexture(0, clamp(uv + float2(-o.x, o.y), 0.0, 1.0)).rgb);
        float bc = lum(amzTexture(0, clamp(uv + float2(0.0, o.y), 0.0, 1.0)).rgb);
        float br = lum(amzTexture(0, clamp(uv + float2(o.x, o.y), 0.0, 1.0)).rgb);
        float gx = -tl - 2.0*ml - bl + tr + 2.0*mr + br;
        float gy = -tl - 2.0*tc - tr + bl + 2.0*bc + br;
        return sqrt(gx*gx + gy*gy);
    }
    float detectEdgeColor(float2 uv, float2 px, float thick) {
        float2 o = px * thick;
        float3 c = amzTexture(0, uv).rgb;
        float3 t = amzTexture(0, clamp(uv + float2(0.0, -o.y), 0.0, 1.0)).rgb;
        float3 b = amzTexture(0, clamp(uv + float2(0.0, o.y), 0.0, 1.0)).rgb;
        float3 l = amzTexture(0, clamp(uv + float2(-o.x, 0.0), 0.0, 1.0)).rgb;
        float3 r = amzTexture(0, clamp(uv + float2(o.x, 0.0), 0.0, 1.0)).rgb;
        float edge = length(t - b) + length(l - r);
        return edge;
    }
    float detectEdgeDepthLike(float2 uv, float2 px, float thick) {
        float2 o = px * thick * 2.0;
        float c = lum(amzTexture(0, uv).rgb);
        float t = lum(amzTexture(0, clamp(uv + float2(0.0, -o.y), 0.0, 1.0)).rgb);
        float b = lum(amzTexture(0, clamp(uv + float2(0.0, o.y), 0.0, 1.0)).rgb);
        float l = lum(amzTexture(0, clamp(uv + float2(-o.x, 0.0), 0.0, 1.0)).rgb);
        float r = lum(amzTexture(0, clamp(uv + float2(o.x, 0.0), 0.0, 1.0)).rgb);
        float laplacian = abs(t + b + l + r - 4.0 * c);
        return laplacian * 2.0;
    }
    void amzRender() {
        float2 uv = amzScreenNorm();
        float taps = getTaps(float(int(amzp_quality)));
        if (amzPass == 0) {
            float2 px = 1.0 / getTexSize((screen.zw/1.0));
            float et = float(int(amzp_edgeType));
            float edge = 0.0;
            if (et < 1.5) {
                edge = detectEdgeLuminance(uv, px, amzp_edgeThickness);
            } else if (et < 2.5) {
                edge = detectEdgeSobel(uv, px, amzp_edgeThickness);
            } else if (et < 3.5) {
                edge = detectEdgeColor(uv, px, amzp_edgeThickness);
            } else {
                edge = detectEdgeDepthLike(uv, px, amzp_edgeThickness);
            }
            edge *= amzp_edgeStrength;
            float soft = max(amzp_edgeSoftness, 0.01);
            edge = smoothstep(amzp_edgeThreshold - soft * 0.5, amzp_edgeThreshold + soft * 0.5, edge);
            if (abs(amzp_edgeContrast) > 0.00001) {
                float c = 1.0 + amzp_edgeContrast;
                edge = clamp((edge - 0.5) * c + 0.5, 0.0, 1.0);
            }
            if (abs(amzp_edgeGamma - 1.0) > 0.00001) {
                edge = pow(max(edge, 0.0), 1.0 / max(amzp_edgeGamma, 0.00001));
            }
            if (amzp_edgeBoost > 0.00001) {
                edge = min(edge * (1.0 + amzp_edgeBoost), 1.0);
            }
            if ((amzp_edgeInvert>0.5)) {
                edge = 1.0 - edge;
            }
            float3 srcColor = amzTexture(0, uv).rgb;
            float3 eColor;
            if ((amzp_useSourceColor>0.5)) {
                eColor = srcColor;
            } else {
                eColor = amzp_edgeColor.rgb;
            }
            if (abs(amzp_edgeSaturation - 1.0) > 0.00001) {
                float eL = lum(eColor);
                eColor = mix(float3(eL), eColor, amzp_edgeSaturation);
            }
            eColor = mix(float3(1.0), eColor, amzp_edgeColorStrength);
            float3 edgeRGB = eColor * edge;
            amzOutput = float4(edgeRGB, edge);
            return;
        }
        if (amzPass == 1) {
            float2 dir = float2(1.0 / getTexSize((screen.zw/2.0)).x, 0.0);
            amzOutput = separableBlur(1, uv, dir, amzp_glowRadius, taps);
            return;
        }
        if (amzPass == 2) {
            float2 dir = float2(0.0, 1.0 / getTexSize((screen.zw/2.0)).y);
            amzOutput = separableBlur(2, uv, dir, amzp_glowRadius, taps);
            return;
        }
        float4 original = amzTexture(0, uv);
        float3 baseRGB = max(original.rgb, 0.0);
        float4 edgeData = amzTexture(1, uv);
        float3 edgeRGB = edgeData.rgb;
        float edgeMask = edgeData.a;
        float4 glowData = amzTexture(3, uv);
        float3 glowRGB = max(glowData.rgb, 0.0);
        float glowMask = max(glowData.a, 0.0);
        float pulse = 1.0;
        if (amzp_pulseSpeed > 0.00001) {
            pulse = 1.0 - amzp_pulseAmount * 0.5 + amzp_pulseAmount * 0.5 * sin(time * amzp_pulseSpeed * 3.14159265359 * 2.0);
        }
        float3 innerG = edgeRGB * amzp_innerGlow * pulse;
        if (amzp_innerSoftness > 0.00001) {
            innerG *= smoothstep(0.0, amzp_innerSoftness, edgeMask);
        }
        if (abs(amzp_glowFalloff - 1.0) > 0.00001) {
            glowRGB = pow(max(glowRGB, 0.0), float3(amzp_glowFalloff * 0.5));
        }
        float3 outerG = glowRGB * amzp_outerGlow * amzp_outerSpread * pulse;
        float3 totalGlow = innerG + outerG * amzp_glowAmount;
        if (amzp_colorMapStrength > 0.00001) {
            float glowIntensity = lum(totalGlow);
            float3 mapped;
            if (glowIntensity > 0.66) {
                float t = (glowIntensity - 0.66) / 0.34;
                mapped = mix(amzp_glowColorMid.rgb, amzp_glowColorCore.rgb, t);
            } else if (glowIntensity > 0.33) {
                float t = (glowIntensity - 0.33) / 0.33;
                mapped = mix(amzp_glowColorOuter.rgb, amzp_glowColorMid.rgb, t);
            } else {
                float t = glowIntensity / 0.33;
                mapped = mix(float3(0.0), amzp_glowColorOuter.rgb, t);
            }
            mapped *= max(glowIntensity * 2.0, 0.0);
            totalGlow = mix(totalGlow, mapped, amzp_colorMapStrength);
        }
        if (amzp_hueRotateSpeed > 0.00001) {
            float3 glowHSL = rgb2hsl(max(totalGlow, 0.0));
            glowHSL.x = fract(glowHSL.x + time * amzp_hueRotateSpeed);
            totalGlow = hsl2rgb(glowHSL);
        }
        if ((amzp_edgeOnly>0.5)) {
            amzOutput = float4(clamp(edgeRGB, 0.0, 1.0), edgeMask);
            return;
        }
        if ((amzp_glowOnly>0.5)) {
            amzOutput = float4(clamp(totalGlow, 0.0, 1.0), clamp(lum(totalGlow) * 3.0, 0.0, 1.0));
            return;
        }
        float3 composited;
        float bm = float(int(amzp_blendMode));
        if (bm < 1.5) {
            composited = baseRGB + totalGlow;
        } else if (bm < 2.5) {
            composited = 1.0 - (1.0 - baseRGB) * (1.0 - clamp(totalGlow, 0.0, 1.0));
        } else if (bm < 3.5) {
            float3 gS = clamp(totalGlow, 0.0, 1.0);
            float3 r;
            r.r = (gS.r<0.5) ? 2.0*baseRGB.r*gS.r+baseRGB.r*baseRGB.r*(1.0-2.0*gS.r) : 2.0*baseRGB.r*(1.0-gS.r)+sqrt(max(baseRGB.r,0.0))*(2.0*gS.r-1.0);
            r.g = (gS.g<0.5) ? 2.0*baseRGB.g*gS.g+baseRGB.g*baseRGB.g*(1.0-2.0*gS.g) : 2.0*baseRGB.g*(1.0-gS.g)+sqrt(max(baseRGB.g,0.0))*(2.0*gS.g-1.0);
            r.b = (gS.b<0.5) ? 2.0*baseRGB.b*gS.b+baseRGB.b*baseRGB.b*(1.0-2.0*gS.b) : 2.0*baseRGB.b*(1.0-gS.b)+sqrt(max(baseRGB.b,0.0))*(2.0*gS.b-1.0);
            composited = r;
        } else {
            composited = mix(baseRGB, totalGlow, clamp(lum(totalGlow) * 2.0, 0.0, 1.0));
        }
        if (amzp_ditherAmt > 0.00001) {
            float2 px = floor(getTexSize((screen.zw/1.0)) * uv);
            float n1 = fract(sin(dot(px, float2(12.9898, 78.233))) * 43758.5453);
            float n2 = fract(sin(dot(px, float2(24.123, 17.321))) * 12345.6789);
            float n3 = fract(sin(dot(px, float2(93.989, 67.345))) * 98765.4321);
            composited += (float3(n1, n2, n3) - 0.5) * amzp_ditherAmt;
        }
        composited = mix(baseRGB, composited, amzp_globalMix);
        composited = clamp(composited, 0.0, 1.0);
        amzOutput = float4(composited, original.a);
    }

half4 main(float2 coord) { amzCoord=coord*2.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

